function CondorcetCurvature(profile P, alternatives n):
    curvature <- 0
    for each ordered triple (a, b, c) in n x n x n:
        if majorityBeats(P, a, b)
           and majorityBeats(P, b, c)
           and majorityBeats(P, c, a):
            curvature <- curvature + 1
    return curvature

function majorityBeats(P, a, b):
    return supportCount(P, a, b) > supportCount(P, b, a)

function supportCount(P, a, b):
    return count of voters r in P with prefers(r, a, b)

